import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DATA-LIST-FIXED.md","filePath":"manual-en/DATA-LIST-FIXED.md","lastUpdated":1785684581000}'),n={name:"manual-en/DATA-LIST-FIXED.md"};function s(r,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h4 id="_8-5-1-data-list-fixed" tabindex="-1">8.5.1 DATA LIST FIXED <a class="header-anchor" href="#_8-5-1-data-list-fixed" aria-label="Permalink to &quot;8.5.1 DATA LIST FIXED&quot;">​</a></h4><pre><code>DATA LIST [FIXED]
        {TABLE,NOTABLE}
        [FILE=’file_name’ [ENCODING=’encoding’]]
        [RECORDS=record_count]
        [END=end_var]
        [SKIP=record_count]
        /[line_no] var_spec…

where each var_spec takes one of the forms
        var_list start-end [type_spec]
        var_list (fortran_spec)
</code></pre><p><code>DATA LIST FIXED</code> is used to read data files that have values at fixed positions on each line of single-line or multiline records. The keyword FIXED is optional.</p><p>The <code>FILE</code> subcommand must be used if input is to be taken from an external file. It may be used to specify a file name as a string or a file handle (see <a href="./File-Handles">File Handles</a>). If the <code>FILE</code> subcommand is not used, then input is assumed to be specified within the command file using <code>BEGIN DATA</code>…<code>END DATA</code> (see <a href="./BEGIN-DATA">BEGIN DATA</a>). The <code>ENCODING</code> subcommand may only be used if the <code>FILE</code> subcommand is also used. It specifies the character encoding of the file. See <a href="./INSERT">INSERT</a>, for information on supported encodings.</p><p>The optional <code>RECORDS</code> subcommand, which takes a single integer as an argument, is used to specify the number of lines per record. If <code>RECORDS</code> is not specified, then the number of lines per record is calculated from the list of variable specifications later in <code>DATA LIST</code>.</p><p>The <code>END</code> subcommand is only useful in conjunction with <code>INPUT PROGRAM</code>. See <a href="./INPUT-PROGRAM">INPUT PROGRAM</a>, for details.</p><p>The optional <code>SKIP</code> subcommand specifies a number of records to skip at the beginning of an input file. It can be used to skip over a row that contains variable names, for example.</p><p><code>DATA LIST</code> can optionally output a table describing how the data file is read. The <code>TABLE</code> subcommand enables this output, and <code>NOTABLE</code> disables it. The default is to output the table.</p><p>The list of variables to be read from the data list must come last. Each line in the data record is introduced by a slash (‘/’). Optionally, a line number may follow the slash. Following, any number of variable specifications may be present.</p><p>Each variable specification consists of a list of variable names followed by a description of their location on the input line. Sets of variables may be specified using the <code>DATA LIST</code> <code>TO</code> convention (see <a href="./Sets-of-Variables">Sets of Variables</a>). There are two ways to specify the location of the variable on the line: columnar style and FORTRAN style.</p><p>In columnar style, the starting column and ending column for the field are specified after the variable name, separated by a dash (‘-’). For instance, the third through fifth columns on a line would be specified ‘3-5’. By default, variables are considered to be in ‘F’ format (see <a href="./Input-and-Output-Formats">Input and Output Formats</a>). (This default can be changed; see <a href="./SET">SET</a> for more information.)</p><p>In columnar style, to use a variable format other than the default, specify the format type in parentheses after the column numbers. For instance, for alphanumeric ‘A’ format, use ‘(A)’.</p><p>In addition, implied decimal places can be specified in parentheses after the column numbers. As an example, suppose that a data file has a field in which the characters ‘1234’ should be interpreted as having the value 12.34. Then this field has two implied decimal places, and the corresponding specification would be ‘(2)’. If a field that has implied decimal places contains a decimal point, then the implied decimal places are not applied.</p><p>Changing the variable format and adding implied decimal places can be done together; for instance, ‘(N,5)’.</p><p>When using columnar style, the input and output width of each variable is computed from the field width. The field width must be evenly divisible into the number of variables specified.</p><p>FORTRAN style is an altogether different approach to specifying field locations. With this approach, a list of variable input format specifications, separated by commas, are placed after the variable names inside parentheses. Each format specifier advances as many characters into the input line as it uses.</p><p>Implied decimal places also exist in FORTRAN style. A format specification with d decimal places also has d implied decimal places.</p><p>In addition to the standard format specifiers (see <a href="./Input-and-Output-Formats">Input and Output Formats</a>), FORTRAN style defines some extensions:</p><p><code>X</code></p><p>Advance the current column on this line by one character position.</p><p><code>T</code>x</p><p>Set the current column on this line to column x, with column numbers considered to begin with 1 at the left margin.</p><p><code>NEWREC</code>x</p><p>Skip forward x lines in the current record, resetting the active column to the left margin.</p><p>Repeat count</p><p>Any format specifier may be preceded by a number. This causes the action of that format specifier to be repeated the specified number of times.</p><p>(spec1, …, specN)</p><p>Group the given specifiers together. This is most useful when preceded by a repeat count. Groups may be nested arbitrarily.</p><p>FORTRAN and columnar styles may be freely intermixed. Columnar style leaves the active column immediately after the ending column specified. Record motion using <code>NEWREC</code> in FORTRAN style also applies to later FORTRAN and columnar specifiers.</p><table tabindex="0"><thead><tr><th>• DATA LIST FIXED Examples</th><th></th><th>Examples of DATA LIST FIXED.</th></tr></thead></table>`,30)])])}const m=a(n,[["render",s]]);export{f as __pageData,m as default};
